package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem string
	DrPrice decimal.Decimal
	DrPct   int64
}

var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.New(0, 0)
var WsNet decimal.Decimal = decimal.New(0, 0)
var WsTotalNet decimal.Decimal = decimal.New(0, 0)
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discRec DiscRec
var discFileReader *bufio.Reader
var discFile *os.File
var inputDone bool

func toDecimalFromDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.New(0, -scale)
	}
	d, err := decimal.NewFromString(s)
	if err != nil {
		var v int64
		fmt.Sscanf(s, "%d", &v)
		d = decimal.NewFromInt(v)
	}
	return d.Shift(-scale)
}

func truncateDecimal(v decimal.Decimal, scale int32) decimal.Decimal {
	return v.Truncate(scale)
}

func storeField(v decimal.Decimal, scale int32, intDigits int) decimal.Decimal {
	tr := truncateDecimal(v, scale)
	// keep low-order digits that fit (mod 10^(intDigits+scale))
	// For positive numbers, this is truncation of high-order digits.
	// Implement via string of scaled integer.
	coeff := tr.Shift(scale) // integer value
	modStr := "1"
	for i := 0; i < intDigits+int(scale); i++ {
		modStr += "0"
	}
	mod, _ := decimal.NewFromString(modStr)
	// handle sign: COBOL PIC 9 is unsigned, but we work with positive.
	// If negative, keep sign? Not needed here.
	if coeff.IsNegative() {
		abs := coeff.Abs()
		r := abs.Mod(mod)
		return r.Neg().Shift(-scale)
	}
	r := coeff.Mod(mod)
	return r.Shift(-scale)
}

func formatEdited(v decimal.Decimal, picture string) string {
	// picture like "ZZ,ZZ9.99" or "ZZ,ZZZ,ZZ9.99"
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	fracDigits := len(fracPic)
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	// truncate toward zero to fracDigits
	v = v.Truncate(int32(fracDigits))

	// get integer and fractional parts
	// v is positive in this program
	neg := v.IsNegative()
	if neg {
		v = v.Abs()
	}
	// integer part
	intPart := v.Truncate(0)
	fracPart := v.Sub(intPart)

	// integer digits string, drop high-order overflow
	// get scaled integer string for intPart
	intStr := intPart.StringFixed(0) // no decimals
	// intStr may be "0"
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	// pad with leading zeros to intDigits
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}

	// fractional string
	fracStr := ""
	if fracDigits > 0 {
		// fracPart * 10^fracDigits
		scale := decimal.New(1, int32(fracDigits))
		f := fracPart.Mul(scale).Truncate(0).Abs()
		fracStr = f.StringFixed(0)
		// fracStr may be shorter
		if len(fracStr) < fracDigits {
			fracStr = strings.Repeat("0", fracDigits-len(fracStr)) + fracStr
		}
		if len(fracStr) > fracDigits {
			fracStr = fracStr[len(fracStr)-fracDigits:]
		}
	}

	// Build int section with commas
	// Map digit positions to intStr indices
	// Collect placeholders
	type ph struct {
		ch   rune
		dIdx int // index in intStr, -1 for comma? handled separately
	}
	var placeholders []rune
	for _, c := range intPic {
		placeholders = append(placeholders, c)
	}
	// Now create result for int section
	dPos := 0
	intRes := make([]rune, len(intPic))
	for i, c := range intPic {
		if c == 'Z' || c == '9' {
			intRes[i] = rune(intStr[dPos])
			dPos++
		} else {
			intRes[i] = c // comma
		}
	}
	// Z suppression
	// Find last Z position? Actually suppression continues until last leading zero replaced,
	// but 9's are never suppressed. Suppression applies to leading zeros in the digit sequence.
	// We need to replace leading zeros (where digit is '0') with spaces, but only while we haven't encountered a non-zero digit.
	// Commas between suppressed digits also become spaces.
	suppressing := true
	for i, c := range intPic {
		if c == 'Z' {
			if suppressing && intRes[i] == '0' {
				intRes[i] = ' '
			} else {
				suppressing = false
			}
		} else if c == '9' {
			// 9 always prints digit, ends suppression
			suppressing = false
		} else if c == ',' {
			if suppressing {
				// if all digits to the right up to next? Actually comma is space if still suppressing
				// Check if still in suppressed zone: if suppression still active, comma becomes space
				intRes[i] = ' '
			}
			// suppression state unchanged
		}
	}
	// Edge: if value is zero, at least the 9 position shows 0, which handled.

	// Combine
	var out string
	if fracDigits > 0 {
		out = string(intRes) + "." + fracStr
	} else {
		out = string(intRes)
	}
	if neg {
		// Not needed for this program, but handle: put minus at leftmost? Keep as is.
		out = "-" + out
	}
	return out
}

func formatPIC9(v int64, digits int) string {
	s := fmt.Sprintf("%d", v)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func parseRecord(line string) DiscRec {
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	drItem := line[0:6]
	drPriceStr := line[6:13]
	drPctStr := line[13:15]
	drPrice := toDecimalFromDigits(drPriceStr, 2)
	var drPct int64
	fmt.Sscanf(strings.TrimSpace(drPctStr), "%d", &drPct)
	// If blank, zero
	// Also handle direct digits including leading zeros
	if strings.TrimSpace(drPctStr) == "" {
		drPct = 0
	}
	return DiscRec{DrItem: drItem, DrPrice: drPrice, DrPct: drPct}
}

func MAINPARA() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if no file, treat as empty
		WsEofFlag = "Y"
		inputDone = true
		SUMMARYPARA()
		return
	}
	discFile = f
	discFileReader = bufio.NewReader(f)
	defer f.Close()
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	SUMMARYPARA()
}

func READPARA() {
	line, err := discFileReader.ReadString('\n')
	if err != nil {
		// EOF: check if we have partial line without newline is handled above? ReadString returns data on EOF
		if len(line) == 0 {
			WsEofFlag = "Y"
			inputDone = true
			return
		}
		// has data, process it then next read will EOF
		line = strings.TrimRight(line, "\r\n")
		discRec = parseRecord(line)
		// Next read will hit EOF, but we need to allow one more iteration.
		// So we buffer: we have consumed this record; set up to detect EOF next time via peek
		// Instead, we handle by not setting done now; next READ will set done.
		// To do that, we need to not lose this record and not set done.
		// So we need to check if err is EOF but line had content: keep not done, and arrange next call signals EOF.
		// Implement via a flag: if err != nil and line != "" we store record and set a pending EOF.
		// Simpler: use manual EOF detection: after this successful parse, next call will attempt read and get EOF.
		// But ReadString already consumed EOF; next ReadString will return 0, EOF.
		// So we succeed now.
		return
	}
	line = strings.TrimRight(line, "\r\n")
	discRec = parseRecord(line)
}

func PROCESSPARA() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	raw := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	rounded := raw.Round(2)
	WsDiscount = storeField(rounded, 2, 5)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	netRaw := discRec.DrPrice.Sub(WsDiscount)
	WsNet = storeField(netRaw, 2, 5)

	WsTotalNet = WsTotalNet.Add(WsNet)
	// WS-TOTAL-NET PIC 9(8)V99 overflow truncated low-order
	WsTotalNet = storeField(WsTotalNet, 2, 8)

	WsCount++

	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	drPctFormatted := formatPIC9(discRec.DrPct, 2)
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, drPctFormatted, WsDiscEd, WsNetEd)

	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	wsCountFormatted := formatPIC9(WsCount, 3)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", wsCountFormatted, WsTotalEd)
}

func main() {
	MAINPARA()
	if discFile != nil {
		discFile.Close()
	}
}
